<body>
<div class="poster">
  <!-- Header -->
  <div class="header">
    <div class="eyebrow">Global Education Report 2023</div>
    <h1>The State of <em>Global Education</em></h1>
    <div class="subtitle">A data-driven look at how far the world has come in expanding education — and the critical gaps in access, quality, and equity that remain</div>
  </div>

  <!-- Hero: 244 Million -->
  <div class="hero">
    <div class="big-number">244<span class="unit">M</span></div>
    <div class="hero-label">Children Out of School</div>
    <div class="hero-sub">Approximately 244 million children of official school age were not enrolled in primary or secondary education in 2023. Secondary-level dropout is a major driver.</div>
  </div>

  <!-- Out of School Breakdown -->
  <div class="section">
    <div class="section-label">01 &middot; Breakdown</div>
    <div class="section-title">Where Are the Missing Children?</div>
    <div class="infographic-box tall" id="chart-out-of-school"></div>
  </div>

  <div class="divider"></div>

  <!-- Historical Progress -->
  <div class="section">
    <div class="section-label">02 &middot; Two Centuries</div>
    <div class="section-title">A Dramatic Transformation Since 1800</div>
    <div class="infographic-box tall" id="chart-historical"></div>
  </div>
  <div class="progress-strip">
    <div class="bar-1800">1800<br>&lt; 1 in 5</div>
    <div class="arrow-marker">&#10132;</div>
    <div class="bar-now">TODAY<br>&gt; 4 in 5 adults educated</div>
  </div>

  <div class="divider"></div>

  <!-- Learning Crisis -->
  <div class="section">
    <div class="section-label">03 &middot; The Learning Crisis</div>
    <div class="section-title">Enrollment Does Not Guarantee Learning</div>
    <div class="infographic-box" id="chart-learning"></div>
  </div>

  <div class="divider"></div>

  <!-- Quality Inequality -->
  <div class="section">
    <div class="section-label">04 &middot; Quality Divide</div>
    <div class="section-title">A World Divided: Learning-Adjusted Years of Schooling</div>
  </div>
  <div class="quality-compare">
    <div class="quality-row">
      <div class="quality-label">Poorest Countries</div>
      <div class="quality-bar-wrap">
        <div class="quality-bar low">&lt; 3 years</div>
      </div>
      <div class="quality-stat" style="color:#ef4444;">&lt;&thinsp;3 yrs</div>
    </div>
    <div class="quality-row">
      <div class="quality-label">South Asia &amp;<br>Sub-Saharan Africa</div>
      <div class="quality-bar-wrap">
        <div class="quality-bar" style="width:58%;background:linear-gradient(90deg,#d97706,#f59e0b);">&lt; 7 years</div>
      </div>
      <div class="quality-stat" style="color:#f59e0b;">&lt;&thinsp;7 yrs</div>
    </div>
    <div class="quality-row">
      <div class="quality-label">Rich Countries</div>
      <div class="quality-bar-wrap">
        <div class="quality-bar high">10+ years</div>
      </div>
      <div class="quality-stat" style="color:#10b981;">10+ yrs</div>
    </div>
  </div>

  <div class="divider"></div>

  <!-- Gender Gap -->
  <div class="section">
    <div class="section-label">05 &middot; Gender Equity</div>
    <div class="section-title">Closing the Gender Gap</div>
  </div>
  <div class="gender-strip">
    <div class="gender-card">
      <div class="level">Primary</div>
      <div class="status">Nearly closed globally</div>
    </div>
    <div class="gender-card">
      <div class="level">Secondary</div>
      <div class="status">Nearly closed globally</div>
    </div>
    <div class="gender-card tertiary">
      <div class="level">Tertiary</div>
      <div class="status">Women exceed men</div>
    </div>
  </div>

  <div class="divider"></div>

  <!-- Infographic: Gender detail -->
  <div class="section">
    <div class="infographic-box short" id="chart-gender"></div>
  </div>

  <!-- Footer -->
  <div class="footer">
    <div class="takeaway">The world has achieved remarkable progress — but the job is far from done. Hundreds of millions of children are either out of school or learning very little while in it. Closing the gap between enrollment and actual learning, and between rich and poor nations, is one of the most pressing challenges of our time.</div>
    <div class="source">Sources: UNESCO Institute for Statistics, World Bank, Our World in Data &middot; 2023</div>
  </div>
</div>

<script src="/app/vendor/infographic.min.js"></script>
<script>
function renderInfographic(id, syntax) {
  try {
    const infographic = new AntVInfographic.Infographic({
      container: '#' + id,
      width: '100%',
      height: '100%',
    });
    infographic.render(syntax.trim());
    return infographic;
  } catch(e) {
    console.error('Render error for ' + id + ':', e);
    return null;
  }
}

// 1. Out of School Breakdown
renderInfographic('chart-out-of-school', `
infographic chart-bar-plain-text
data
  title Children Out of School by Level
  desc 2023 estimates, in millions
  values
    - label Primary Age
      value 60
    - label Secondary Age
      value 184
theme
  palette #ef4444 #f59e0b
`);

// 2. Historical Progress
renderInfographic('chart-historical', `
infographic compare-binary-horizontal-simple-fold
data
  title Two Centuries of Progress
  desc Adults aged 15 and older with any formal education
  compares
    - label 1800
      children
        - label Less than 1 in 5
          value 20
          desc Fewer than 1 in 5 adults had any formal education
          icon user
    - label Today
      children
        - label More than 4 in 5
          value 80
          desc Over 4 in 5 adults have received formal education
          icon user check
theme
  palette #64748b #3b82f6
`);

// 3. Learning Crisis
renderInfographic('chart-learning', `
infographic list-grid-badge-card
data
  title The Learning Crisis
  desc In many lower-income countries, enrollment masks a severe learning deficit
  lists
    - label Reading Proficiency
      desc Fewer than 20 percent of children achieve minimum reading proficiency by the end of primary school
      icon book open
    - label Hidden Crisis
      desc Being enrolled does not guarantee quality learning outcomes
      icon alert triangle
theme
  palette #ef4444 #f59e0b
`);

// 4. Gender Gap
renderInfographic('chart-gender', `
infographic list-column-simple-vertical-arrow
data
  title Gender Gap in Education
  desc Global enrollment parity status, 2023
  lists
    - label Primary
      desc Nearly closed globally
    - label Secondary
      desc Nearly closed globally
    - label Tertiary
      desc Women now exceed men in enrollment
theme
  palette #8b5cf6 #06b6d4 #10b981
`);
</script>
</body>
</html>
