import { chromium } from 'playwright';
import { fileURLToPath } from 'url';
import path from 'path';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const htmlPath = path.resolve(__dirname, 'poster.html');
const outputPath = path.resolve(__dirname, 'final_poster.png');

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage();

// Design width is 794px. A1 at 150 DPI = 3508px wide.
// deviceScaleFactor of ~4.42 gives us A1 width at 150 DPI.
const DESIGN_WIDTH = 794;
const TARGET_A1_WIDTH_150DPI = 3508;
const scale = TARGET_A1_WIDTH_150DPI / DESIGN_WIDTH;

await page.setViewportSize({
  width: DESIGN_WIDTH,
  height: 1200,
});

await page.goto('file://' + htmlPath, { waitUntil: 'networkidle' });

// Wait for all infographic SVGs to render
await page.waitForTimeout(2000);

// Get full page height
const bodyHandle = await page.$('.poster');
const box = await bodyHandle.boundingBox();
const fullHeight = Math.ceil(box.height);

// Set viewport to full poster dimensions
await page.setViewportSize({
  width: DESIGN_WIDTH,
  height: fullHeight + 20,
});

await page.waitForTimeout(500);

// Screenshot just the poster element at high scale
await bodyHandle.screenshot({
  path: outputPath,
  scale: 'device',
  type: 'png',
});

console.log(`Poster rendered: ${outputPath}`);
console.log(`Dimensions: ${DESIGN_WIDTH}x${fullHeight} at device scale factor`);

// Now scale to A1 150 DPI using canvas approach through evaluate
// Take a high-res screenshot by using deviceScaleFactor
await page.close();

// Re-open with higher deviceScaleFactor
const page2 = await browser.newPage();
await page2.setViewportSize({
  width: DESIGN_WIDTH,
  height: fullHeight + 20,
  deviceScaleFactor: scale,
});

await page2.goto('file://' + htmlPath, { waitUntil: 'networkidle' });
await page2.waitForTimeout(2000);

const bodyHandle2 = await page2.$('.poster');
await bodyHandle2.screenshot({
  path: outputPath,
  type: 'png',
});

console.log(`High-res poster rendered: ${outputPath}`);
console.log(`Device scale factor: ${scale}`);
console.log(`Output ~${Math.round(DESIGN_WIDTH * scale)}x${Math.round(fullHeight * scale)} px`);

await browser.close();

