    line-height: 1.45;
  }

  /* Sections */
  .section { padding: 4px 48px 0; }
  .section-row {
    display: flex;
    align-items: center;
    gap: 4px;
  }
  .section-label {
    font-size: 8px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 3px;
    color: #f59e0b;
    margin-bottom: 0px;
  }
  .section-title {
    font-size: 15px;
    font-weight: 700;
    color: #f1f5f9;
    margin-bottom: 6px;
    letter-spacing: -0.3px;
  }

  .infographic-box {
    width: 100%;
    height: 154px;
    background: rgba(255,255,255,0.015);
    border-radius: 5px;
    border: 1px solid rgba(255,255,255,0.04);
  }
  .infographic-box.sm { height: 138px; }

  /* Quality compare bars */
  .quality-compare {
    padding: 2px 48px;
    display: flex;
    flex-direction: column;
    gap: 5px;
  }
  .quality-row {
    display: flex;
    align-items: center;
    gap: 12px;
  }
  .quality-label {
    width: 115px;
    text-align: right;
    font-size: 10px;
    font-weight: 600;
    color: #94a3b8;
    flex-shrink: 0;
    line-height: 1.3;
  }
  .quality-bar-wrap {
    flex: 1;
    height: 28px;
    background: rgba(255,255,255,0.03);
    border-radius: 3px;
    overflow: hidden;
  }
  .quality-bar {
    height: 100%;
    border-radius: 3px;
    display: flex;
    align-items: center;
    padding-left: 10px;
    font-size: 12px;
    font-weight: 800;
    color: #fff;
  }
  .quality-stat {
    font-size: 14px;
    font-weight: 800;
    color: #f1f5f9;
    flex-shrink: 0;
    width: 65px;
  }

  /* Gender cards */
  .gender-strip {
    padding: 4px 48px;
    display: flex;
    gap: 10px;
  }
  .gender-card {
    flex: 1;
    background: rgba(255,255,255,0.025);
    border: 1px solid rgba(255,255,255,0.06);
    border-radius: 5px;
    padding: 12px 14px;
    text-align: center;
  }
  .gender-card .level {
    font-size: 11px;
    font-weight: 700;
    color: #f1f5f9;
  }
  .gender-card .status {
    font-size: 9px;
    color: #10b981;
    margin-top: 3px;
    font-weight: 600;
    letter-spacing: 0.3px;
  }
  .gender-card.tertiary .status { color: #a78bfa; }
  .gender-card .note {
    font-size: 8px;
    color: #64748b;
    margin-top: 2px;
  }

  /* Footer */
  .footer {
    padding: 14px 52px 18px;
    text-align: center;
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
  }
  .footer .takeaway {
    font-size: 11px;
    font-weight: 600;
    color: #cbd5e1;
    line-height: 1.5;
    max-width: 520px;
    margin: 0 auto;
    position: relative;
  }
  .footer .takeaway::before {
    content: '';
    display: block;
    width: 32px;
    height: 2px;
    background: #f59e0b;
    margin: 0 auto 8px;
