  .footer .source {
    font-size: 8px;
    color: #475569;
    margin-top: 8px;
  }

  .divider {
    height: 1px;
    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.06), transparent);
    margin: 6px 68px;
  }
</style>
