<body>
<div class="poster">
  <div class="header">
    <div class="eyebrow">Global Education Report 2023</div>
    <h1>The State of <em>Global Education</em></h1>
    <div class="subtitle">Progress, gaps, and inequality in education access, quality, and equity worldwide</div>
  </div>

  <div class="hero">
    <div class="big-number">244<span class="unit">M</span></div>
    <div class="hero-label">Children Out of School</div>
    <div class="hero-sub">244 million children of school age were not enrolled in primary or secondary education in 2023 — secondary-age dropout is the major driver</div>
  </div>

  <div class="section">
    <div class="section-label">01 &middot; Out of School Breakdown</div>
    <div class="section-title">Where Are the Missing Children?</div>
    <div class="infographic-box sm" id="chart-out-of-school"></div>
  </div>

  <div class="divider"></div>

  <div class="section">
    <div class="section-label">02 &middot; Two Centuries of Progress</div>
    <div class="section-title">A Dramatic Transformation Since 1800</div>
    <div class="infographic-box sm" id="chart-historical"></div>
  </div>

  <div class="divider"></div>

  <div class="section">
    <div class="section-label">03 &middot; The Learning Crisis</div>
    <div class="section-title">Enrollment Does Not Guarantee Learning</div>
    <div class="infographic-box sm" id="chart-learning"></div>
  </div>

  <div class="divider"></div>

  <div class="section">
    <div class="section-label">04 &middot; Quality Divide</div>
    <div class="section-title">A World Divided: Learning-Adjusted Years of Schooling (2020)</div>
  </div>
  <div class="quality-compare">
    <div class="quality-row">
      <div class="quality-label">Poorest Countries</div>
      <div class="quality-bar-wrap"><div class="quality-bar" style="width:23%;background:linear-gradient(90deg,#dc2626,#ef4444);">&lt;&thinsp;3 years</div></div>
      <div class="quality-stat" style="color:#ef4444;">&lt;&thinsp;3</div>
    </div>
    <div class="quality-row">
      <div class="quality-label">South Asia &amp; Sub-Saharan Africa</div>
      <div class="quality-bar-wrap"><div class="quality-bar" style="width:58%;background:linear-gradient(90deg,#d97706,#f59e0b);">&lt;&thinsp;7 years</div></div>
      <div class="quality-stat" style="color:#f59e0b;">&lt;&thinsp;7</div>
    </div>
    <div class="quality-row">
      <div class="quality-label">High-Income Countries</div>
      <div class="quality-bar-wrap"><div class="quality-bar" style="width:83%;background:linear-gradient(90deg,#059669,#10b981);">10+ years</div></div>
      <div class="quality-stat" style="color:#10b981;">10+</div>
    </div>
  </div>

  <div class="divider"></div>

  <div class="section">
    <div class="section-label">05 &middot; Gender Equity</div>
    <div class="section-title">Closing the Gender Gap (2023)</div>
  </div>
  <div class="gender-strip">
    <div class="gender-card">
      <div class="level">Primary</div>
      <div class="status">Nearly Closed</div>
      <div class="note">Boys &amp; girls near parity</div>
    </div>
    <div class="gender-card">
      <div class="level">Secondary</div>
      <div class="status">Nearly Closed</div>
      <div class="note">Boys &amp; girls near parity</div>
    </div>
    <div class="gender-card tertiary">
      <div class="level">Tertiary</div>
      <div class="status">Women Exceed Men</div>
      <div class="note">Young women now lead</div>
    </div>
  </div>

  <div class="footer">
    <div class="takeaway">The world has achieved remarkable progress &mdash; but hundreds of millions of children remain out of school or learning very little. Closing the gap between enrollment and actual learning is one of the most pressing challenges of our time.</div>
    <div class="source">Sources: UNESCO Institute for Statistics &middot; World Bank &middot; Our World in Data &middot; 2023</div>
  </div>
</div>

<script src="/app/vendor/infographic.min.js"></script>
<script>
function renderInfographic(id, syntax) {
  try {
    const infographic = new AntVInfographic.Infographic({
      container: '#' + id,
      width: '100%',
      height: '100%',
    });
    infographic.render(syntax.trim());
    return infographic;
  } catch(e) {
    console.error('Render error for ' + id + ':', e);
    return null;
  }
}

renderInfographic('chart-out-of-school', `
infographic chart-bar-plain-text
data
  title Children Out of School by Level
  desc 2023 estimates, in millions
  values
    - label Primary Age
      value 60
    - label Secondary Age
      value 184
theme
  palette #ef4444 #f59e0b
`);

renderInfographic('chart-historical', `
infographic compare-binary-horizontal-simple-fold
data
  title Two Centuries of Progress
  desc Adults aged 15 and older with any formal education
  compares
    - label 1800
      children
        - label Less than 1 in 5
          value 20
          desc Fewer than 1 in 5 adults had any formal education
          icon user
    - label Today
      children
        - label More than 4 in 5
          value 80
          desc Over 4 in 5 adults have received formal education
          icon user check
theme
  palette #64748b #3b82f6
`);

renderInfographic('chart-learning', `
infographic list-grid-badge-card
data
  title The Learning Crisis
  desc In many lower-income countries, being enrolled does not mean learning
  lists
    - label Reading Proficiency
      desc Fewer than 20 percent of children achieve minimum reading proficiency by the end of primary school
      icon book open
    - label Hidden Crisis
      desc Enrollment numbers mask a severe deficit in actual learning outcomes
      icon alert triangle
theme
  palette #ef4444 #f59e0b
`);
</script>
