const { chromium } = require('playwright');
const path = require('path');

const htmlPath = path.resolve(__dirname, 'poster.html');
const outputPath = path.resolve(__dirname, 'final_poster.png');

(async () => {
  const browser = await chromium.launch({ headless: true });

  // A1 at 150 DPI: 3508 x 4961 px
  // Design: 794 x 1123 px
  const DESIGN_WIDTH = 794;
  const DESIGN_HEIGHT = 1123;
  const TARGET_WIDTH = 3508;
  const scale = TARGET_WIDTH / DESIGN_WIDTH; // ~4.418

  const page = await browser.newPage();
  await page.setViewportSize({
    width: DESIGN_WIDTH,
    height: DESIGN_HEIGHT + 20,
    deviceScaleFactor: scale,
  });

  await page.goto('file://' + htmlPath, { waitUntil: 'networkidle' });
  await page.waitForTimeout(3000);

  const posterEl = await page.$('.poster');
  await posterEl.screenshot({ path: outputPath, type: 'png' });

  const outW = Math.round(DESIGN_WIDTH * scale);
  const outH = Math.round(DESIGN_HEIGHT * scale);
  console.log(`Poster rendered: ${outputPath}`);
  console.log(`Output: ~${outW}x${outH} px`);
  console.log(`A1@150dpi target: 3508x4961 px`);

  await browser.close();
})();

