const { chromium } = require('playwright');
const path = require('path');

const htmlPath = path.resolve(__dirname, 'poster.html');
const outputPath = path.resolve(__dirname, 'final_poster.png');

(async () => {
  const browser = await chromium.launch({ headless: true });

  // A1 at 150 DPI: 3508 x 4961 px
  // Design: 794 x 1123 px at ~4.418x scale
  const DESIGN_WIDTH = 794;
  const DESIGN_HEIGHT = 1123;
  const TARGET_WIDTH = 3508;
  const scale = TARGET_WIDTH / DESIGN_WIDTH;

  // Use a larger viewport with deviceScaleFactor, then clip to poster
  const page = await browser.newPage();
  await page.setViewportSize({
    width: Math.ceil(DESIGN_WIDTH * scale),
    height: Math.ceil(DESIGN_HEIGHT * scale),
  });

  await page.goto('file://' + htmlPath, { waitUntil: 'networkidle' });
  await page.waitForTimeout(3000);

  // Scale the poster element to fill the viewport
  await page.addStyleTag({
    content: `.poster { transform: scale(${scale}); transform-origin: top left; }`
  });
  await page.waitForTimeout(500);

  // Get poster bounding box after transform
  const posterEl = await page.$('.poster');
  const box = await posterEl.boundingBox();

  // Screenshot clipped to the scaled poster area
  await page.screenshot({
    path: outputPath,
    type: 'png',
    clip: {
      x: box.x,
      y: box.y,
      width: box.width,
      height: box.height,
    },
  });

  console.log(`Poster rendered: ${outputPath}`);
  console.log(`Output: ${Math.round(box.width)}x${Math.round(box.height)} px`);
  console.log(`A1@150dpi target: 3508x4961 px`);

  await browser.close();
})();

