arguments.content:
const { chromium } = require('playwright');
const path = require('path');

const htmlPath = path.resolve(__dirname, 'poster.html');
const outputPath = path.resolve(__dirname, 'final_poster.png');

(async () => {
  const browser = await chromium.launch({ headless: true });

  const DESIGN_WIDTH = 794;
  const DESIGN_HEIGHT = 1123;
  const SCALE = 4.418;
  const outW = Math.round(DESIGN_WIDTH * SCALE);
  const outH = Math.round(DESIGN_HEIGHT * SCALE);

  const page = await browser.newPage();
  await page.setViewportSize({ width: outW, height: outH });

  await page.goto('file://' + htmlPath, { waitUntil: 'networkidle' });
  await page.waitForTimeout(2000);

  // Inject CSS to natively scale the poster to target dimensions
  // by overriding pixel values with scaled equivalents
  await page.addStyleTag({
    content: `
      .poster {
        width: ${outW}px !important;
        height: ${outH}px !important;
        font-size: ${Math.round(16 * SCALE)}px !important;
      }
      .poster .big-number { font-size: ${Math.round(120 * SCALE)}px !important; }
      .poster .big-number .unit { font-size: ${Math.round(34 * SCALE)}px !important; }
      .poster h1 { font-size: ${Math.round(27 * SCALE)}px !important; }
      .poster .hero-label { font-size: ${Math.round(18 * SCALE)}px !important; }
      .poster .section-title { font-size: ${Math.round(15 * SCALE)}px !important; }
      .poster .eyebrow { font-size: ${Math.round(9 * SCALE)}px !important; }
      .poster .subtitle { font-size: ${Math.round(11 * SCALE)}px !important; }
      .poster .hero-sub { font-size: ${Math.round(10 * SCALE)}px !important; }
      .poster .section-label { font-size: ${Math.round(8 * SCALE)}px !important; }
      .poster .quality-label { font-size: ${Math.round(10 * SCALE)}px !important; }
      .poster .quality-bar { font-size: ${Math.round(12 * SCALE)}px !important; }
      .poster .quality-stat { font-size: ${Math.round(14 * SCALE)}px !important; }
      .poster .gender-card .level { font-size: ${Math.round(11 * SCALE)}px !important; }
      .poster .gender-card .status { font-size: ${Math.round(9 * SCALE)}px !important; }
      .poster .gender-card .note { font-size: ${Math.round(8 * SCALE)}px !important; }
      .poster .takeaway { font-size: ${Math.round(11 * SCALE)}px !important; }
      .poster .source { font-size: ${Math.round(8 * SCALE)}px !important; }
      .poster .infographic-box { height: ${Math.round(138 * SCALE)}px !important; }
      .poster .quality-bar-wrap { height: ${Math.round(28 * SCALE)}px !important; }
      .poster .quality-row { gap: ${Math.round(12 * SCALE)}px !important; }
      .poster .quality-compare { gap: ${Math.round(5 * SCALE)}px !important; padding: ${Math.round(2 * SCALE)}px 48px !important; }
      .poster .gender-strip { gap: ${Math.round(10 * SCALE)}px !important; }
      .poster .section { padding: ${Math.round(4 * SCALE)}px 48px 0 !important; }
      .poster .header { padding: ${Math.round(28 * SCALE)}px 52px 0 !important; }
      .poster .hero { padding: ${Math.round(14 * SCALE)}px 52px ${Math.round(8 * SCALE)}px !important; }
      .poster .footer { padding: ${Math.round(14 * SCALE)}px 52px ${Math.round(18 * SCALE)}px !important; }
      .poster .divider { margin: ${Math.round(6 * SCALE)}px 68px !important; }
      .poster .quality-label { width: ${Math.round(115 * SCALE)}px !important; }
      .poster .quality-stat { width: ${Math.round(65 * SCALE)}px !important; }
    `
  });

  // Also scale the infographic containers and re-render them
  await page.evaluate((scale) => {
    // Scale infographic boxes - we need to re-render with new dimensions
    // First, remove existing infographic SVGs
    document.querySelectorAll('.infographic-box').forEach(box => {
      box.innerHTML = '';
    });
  }, SCALE);

  await page.waitForTimeout(500);

  // Re-render infographics (the script already ran once, but we cleared them)
  // The infographic library should re-render at the new container sizes
  await page.evaluate(() => {
    const boxes = document.querySelectorAll('.infographic-box');
    boxes.forEach(box => {
      const id = box.id;
      if (!id) return;
      // Re-trigger rendering by re-running the script
      const infographic = new AntVInfographic.Infographic({
        container: '#' + id,
        width: '100%',
        height: '100%',
      });
      // We need to re-parse the syntax. Since we can't easily get it,
      // let's re-initialize from scratch.
    });
  });

  // This approach is getting complex. Let me just use CSS transform scale
  // which is simpler. SVG content scales smoothly.

  // Reset and use simpler approach
  await page.goto('file://' + htmlPath, { waitUntil: 'networkidle' });
  await page.waitForTimeout(3000);

  // Remove body centering
  await page.evaluate(() => {
    document.body.style.display = 'block';
    document.body.style.margin = '0';
    document.body.style.padding = '0';
    document.body.style.background = '#0a1628';
  });

  // Scale poster using CSS transform - SVG elements scale crisply
  await page.evaluate((s) => {
    const poster = document.querySelector('.poster');
    poster.style.transform = `scale(${s})`;
    poster.style.transformOrigin = '0 0';
    poster.style.position = 'absolute';
    poster.style.top = '0';
    poster.style.left = '0';
  }, SCALE);

  await page.waitForTimeout(1000);

  // Screenshot clipped to the scaled poster area (794 * SCALE x 1123 * SCALE)
  await page.screenshot({
    path: outputPath,
    type: 'png',
    clip: { x: 0, y: 0, width: outW, height: outH },
  });

  const { readFileSync } = require('fs');
  const buf = readFileSync(outputPath);
  const w = buf.readUInt32BE(16);
  const h = buf.readUInt32BE(20);
  console.log(`Poster rendered: ${outputPath}`);
  console.log(`Output dimensions: ${w}x${h} px`);
  console.log(`Target A1@150dpi: 3508x4961 px`);

  await browser.close();
})();

