const { chromium } = require('playwright');
const path = require('path');

const htmlPath = path.resolve(__dirname, 'poster.html');
const outputPath = path.resolve(__dirname, 'final_poster.png');

(async () => {
  const browser = await chromium.launch({ headless: true });

  const SCALE = 4.418;
  const DESIGN_W = 794;
  const DESIGN_H = 1123;
  const outW = Math.round(DESIGN_W * SCALE);
  const outH = Math.round(DESIGN_H * SCALE);

  const page = await browser.newPage();
  // Viewport must be large enough to hold the transformed poster
  await page.setViewportSize({ width: outW + 100, height: outH + 100 });

  await page.goto('file://' + htmlPath, { waitUntil: 'networkidle' });
  await page.waitForTimeout(3000);

  // Remove body centering, set matching background, scale poster
  await page.evaluate((s) => {
    document.body.style.display = 'block';
    document.body.style.margin = '0';
    document.body.style.padding = '0';
    document.body.style.background = '#0a1628';
    const poster = document.querySelector('.poster');
    poster.style.transform = `scale(${s})`;
    poster.style.transformOrigin = '0 0';
  }, SCALE);

  await page.waitForTimeout(1000);

  // Screenshot: clip to the scaled poster area in CSS pixels
  // Since transform doesn't change CSS box, poster is still 794x1123 CSS px.
  // But the viewport captures the visual (transformed) rendering.
  // Full page screenshot captures the transformed visual output.
  await page.screenshot({
    path: outputPath,
    type: 'png',
    clip: { x: 0, y: 0, width: outW, height: outH },
  });

  const { readFileSync } = require('fs');
  const buf = readFileSync(outputPath);
  const w = buf.readUInt32BE(16);
  const h = buf.readUInt32BE(20);
  console.log(`Poster rendered: ${outputPath}`);
  console.log(`Output dimensions: ${w}x${h} px`);
  console.log(`Target A1@150dpi: 3508x4961 px`);

  await browser.close();
})();

